    "faq_student_desk": "Student Help Desk",
    "faq_q1": "📸 Photo & Signature Resizer kaise kaam karta hai? Kya meri photo safe hai?",
    "faq_a1": "Aapki photo aur signature 100% safe hai. Ye tool browser ke andar (Client-side HTML5 Canvas) kaam karta hai, server par upload nahi hota. SSC, UPSC, Railway aur Police forms ke anusaar 20-50 KB turant resize ho jata hai.",
    "faq_q2": "📑 Official Notification Circular Decoder kya hai?",
    "faq_a2": "50-60 pages ke lambe notifications ko short karke last date, total vacancy, salary, age limit aur syllabus 1 minute me aasan bhasha me samjhata hai.",
    "faq_q3": "📚 ₹10 Study Notes aur PYQs kaise download karein?",
    "faq_a3": "Exam choose karke PhonePe, Google Pay ya Paytm se bas ₹10 ka UPI payment karein aur turant high quality PDF download karein.",
    "faq_q4": "🎂 Age Calculator me reservation relaxation kaise calculate hota hai?",
    "faq_a4": "Official cutoff date aur date of birth ke basis par OBC 3 saal, SC/ST 5 saal aur PwBD 10-15 saal ki chhoot automatically calculate hoti hai.",
    "faq_q5": "🌐 Kya portal par sabhi links 100% official hain?",
