    "anskey_notice": "<strong>முக்கிய அறிவிப்பு:</strong> ஆட்சேபனைகளை பதிவு செய்ய அதிகாரப்பூர்வ ஆணைய இணையதளத்தில் உள்நுழையவும். சரியான ஆட்சேபனைகளுக்கு மட்டுமே கட்டணம் திரும்ப வழங்கப்படும்.",
    "modal_hall_tag": "அதிகாரப்பூர்வ தேர்வு அறை நெறிமுறை • OMR பொன்னான விதிகள்",
    "modal_hall_title": "தேர்வு நாள் அறை முதன்மை சரிபார்ப்பு & OMR விதிகள்",
    "modal_hall_warning": "<strong>பயோமெட்ரிக் & நுழைவு வாயில் மூடல் எச்சரிக்கை:</strong> அட்மிட் கார்டில் குறிப்பிடப்பட்டுள்ள நேரத்திற்கு 45 நிமிடங்களுக்கு முன்பே தேர்வு மையத்தை அடையுங்கள்.",
    "modal_sec_mandatory": "✅ 1. கட்டாய ஆவணங்கள் (இந்த 4 பொருட்களை தவறாமல் எடுத்துச் செல்லுங்கள்)",
    "modal_doc1_title": "📄 1. அசல் அட்மிட் கார்டு (அச்சு நகல்)",
    "modal_doc1_desc": "வண்ண அல்லது தெளிவான அச்சு. பார்கோடு மற்றும் பதிவு எண் மடிக்கப்படக்கூடாது.",
    "modal_doc2_title": "🪪 2. அசல் புகைப்பட அடையாள அட்டை (முழு பிறந்த தேதியுடன்)",
    "modal_doc2_desc": "ஆதார் அட்டை / வாக்காளர் அடையாள அட்டை / பான் அட்டை / ஓட்டுநர் உரிமம். மொபைல் நகல்கள் செல்லாது.",
    "modal_doc3_title": "🖼️ 3. பாஸ்போர்ட் அளவு புகைப்படங்கள் (2 புகைப்படங்கள்)",
    "modal_doc3_desc": "வருகை தாளில் ஒட்டுவதற்கு அட்மிட் கார்டில் உள்ள புகைப்படத்தை ஒத்த 2 புகைப்படங்கள்.",
    "modal_doc4_title": "🖊️ 4. வெளிப்படையான பால்பாயிண்ட் பேனா (கருப்பு / நீலம்)",
    "modal_doc4_desc": "வெளிப்படையான கருப்பு அல்லது நீல பால் பேனா மட்டுமே. ஜெல் பேனா அல்லது பென்சில் தடைசெய்யப்பட்டுள்ளது.",
    "modal_sec_barred": "🚫 2. முற்றிலும் தடைசெய்யப்பட்ட பொருட்கள் (ஜீரோ டாலரன்ஸ்)",
    "modal_sec_omr": "🎯 3. OMR தாள் நிரப்புவதற்கான 5 பொன்னான விதிகள்",
    "modal_omr_r1_title": "வட்டத்தை முழுமையாக நிரப்பவும் (முழுமையான கருப்பு வட்டம்):",
    "modal_omr_r1_desc": "வட்டத்திற்கு வெளியே எழுதாதீர்கள் அல்லது டிக் (✓) செய்யாதீர்கள். முழுமையாக நிரப்பப்பட்ட வட்டங்கள் மட்டுமே ஸ்கேன் செய்யப்படும்.",
    "modal_omr_r2_title": "பதிவு எண் மற்றும் கேள்வித்தாள் குறியீட்டை கவனமாக நிரப்பவும்:",
    "modal_omr_r2_desc": "கேள்விகளுக்கு பதிலளிக்கும் முன் பதிவு எண் மற்றும் வினாத்தாள் வரிசையை பிழையின்றி நிரப்பவும்.",
    "modal_omr_r3_title": "ஒரு கேள்விக்கு ஒரே ஒரு வட்டத்தை மட்டுமே நிரப்பவும்:",
    "modal_omr_r3_desc": "இரண்டு வட்டங்களை நிரப்பினால் அந்த பதில் நிராகரிக்கப்பட்டு எதிர்மறை மதிப்பெண் வழங்கப்படும்.",
    "modal_omr_r4_title": "OMR தாளை மடிக்காதீர்கள், ஒயிட்னர் பயன்படுத்தாதீர்கள்:",
    "modal_omr_r4_desc": "பிளேடால் கீறுவது அல்லது ஒயிட்னர் பயன்படுத்துவது முற்றிலும் தடைசெய்யப்பட்டுள்ளது.",
    "modal_omr_r5_title": "தேர்வுக் கண்காணிப்பாளர் கையொப்பம் & கைரேகை சரிபார்ப்பு:",
    "modal_omr_r5_desc": "தேர்வு முடிவதற்குள் கண்காணிப்பாளர் OMR தாளில் கையொப்பமிட்டுள்ளாரா என்பதை உறுதிப்படுத்தவும்.",
