    "faq_a1": "আপনার ছবি এবং স্বাক্ষর ১০০% নিরাপদ। এই টুলটি ব্রাউজারের মধ্যে (Client-side HTML5 Canvas) প্রক্রিয়া সম্পন্ন করে, সার্ভারে আপলোড হয় না। SSC, UPSC, রেলওয়ে ও পুলিশের জন্য ২০-৫০ KB সাইজে দ্রুত তৈরি করে দেয়।",
    "faq_q2": "📑 অফিসিয়াল বিজ্ঞপ্তি সার্কুলার ডিকোডার কী?",
    "faq_a2": "৫০-৬০ পৃষ্ঠার জটিল বিজ্ঞপ্তির গুরুত্বপূর্ণ তথ্য যেমন আবেদনের শেষ তারিখ, শূন্যপদ, বেতন, বয়সসীমা ও সিলেবাস ১ মিনিটে সহজ বাংলায় উপস্থাপন করে।",
    "faq_q3": "📚 ₹১০ স্টাডি নোটস এবং পূর্ববর্তী বছরের প্রশ্ন (PYQ) কীভাবে পাবেন?",
    "faq_a3": "পরীক্ষা নির্বাচন করে পছন্দের নোট বেছে নিন। PhonePe, Google Pay বা Paytm দিয়ে ₹১০ ইউপিআই পেমেন্ট করে তাৎক্ষণিক উচ্চ মানের PDF ডাউনলোড করুন।",
    "faq_q4": "🎂 বয়স গণনায় (Age Calculator) সংরক্ষণের ছাড় কীভাবে গণনা করা হয়?",
    "faq_a4": "অফিসিয়াল কাটঅফ তারিখ ও জন্মতারিখ অনুযায়ী OBC ৩ বছর, SC/ST ৫ বছর ও PwBD ১০-১৫ বছরের ছাড় স্বয়ংক্রিয়ভাবে হিসাব করা হয়।",
    "faq_q5": "🌐 পোর্টালের সমস্ত লিঙ্ক কি ১০০% অফিসিয়াল?",
    "faq_a5": "হ্যাঁ! সমস্ত লিঙ্ক ২৪x৭ সরকারি পোর্টাল (.gov.in, .nic.in) থেকে স্বয়ংক্রিয়ভাবে যাচাই করা হয়।",
