    "faq_q1": "📸 ફોટો અને સહી રિસાઈઝર કેવી રીતે કામ કરે છે? શું મારો ફોટો સુરક્ષિત છે?",
    "faq_a1": "તમારો ફોટો અને સહી ૧૦૦% સુરક્ષિત છે. આ ટૂલ બ્રાઉઝરમાં જ (Client-side HTML5 Canvas) પ્રોસેસ કરે છે. SSC, UPSC, રેલવે અને પોલીસ ભરતી માટે ૨૦-૫૦ KB માં તરત કન્વર્ટ કરે છે.",
