    "faq_a3": "પરીક્ષા પસંદ કરી PhonePe, Google Pay અથવા Paytm દ્વારા ₹૧૦ નું UPI પેમેન્ટ કરી તરત જ ઉચ્ચ ગુણવત્તાવાળી PDF ડાઉનલોડ કરો.",
