    "faq_q1": "📸 ಫೋಟೋ ಮತ್ತು ಸಹಿ ಮರುಗಾತ್ರಗೊಳಿಸುವಿಕೆ ಹೇಗೆ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ? ನನ್ನ ಫೋಟೋ ಸುರಕ್ಷಿತವೇ?",
    "faq_a1": "ನಿಮ್ಮ ಫೋಟೋ ಮತ್ತು ಸಹಿ 100% ಸುರಕ್ಷಿತವಾಗಿದೆ. ಈ ಉಪಕರಣವು ಬ್ರೌಸರ್‌ನಲ್ಲಿಯೇ (Client-side HTML5 Canvas) ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ. SSC, UPSC, ರೈಲ್ವೆ ಮತ್ತು ಪೊಲೀಸ್ ಅರ್ಜಿಗಳಿಗೆ 20-50 KB ಗೆ ನಿಖರವಾಗಿ ಬದಲಾಯಿಸುತ್ತದೆ.",
