    "faq_q1": "📸 ਫੋਟੋ ਅਤੇ ਦਸਤਖਤ ਰੀਸਾਈਜ਼ਰ ਕਿਵੇਂ ਕੰਮ ਕਰਦਾ ਹੈ? ਕੀ ਮੇਰੀ ਫੋਟੋ ਸੁਰੱਖਿਅਤ ਹੈ?",
    "faq_a1": "ਤੁਹਾਡੀ ਫੋਟੋ ਅਤੇ ਦਸਤਖਤ 100% ਸੁਰੱਖਿਅਤ ਹਨ। ਇਹ ਟੂਲ ਬ੍ਰਾਊਜ਼ਰ ਦੇ ਅੰਦਰ (Client-side HTML5 Canvas) ਚੱਲਦਾ ਹੈ। SSC, UPSC, ਰੇਲਵੇ ਅਤੇ ਪੁਲਿਸ ਭਰਤੀ ਲਈ 20-50 KB ਵਿੱਚ ਤੁਰੰਤ ਰੀਸਾਈਜ਼ ਕਰਦਾ ਹੈ।",
    "faq_q2": "📑 ਅਧਿਕਾਰਤ ਨੋਟੀਫਿਕੇਸ਼ਨ ਸਰਕੂਲਰ ਡੀਕੋਡਰ ਕੀ ਹੈ?",
    "faq_a2": "50-60 ਪੰਨਿਆਂ ਦੇ ਨੋਟੀਫਿਕੇਸ਼ਨ ਵਿੱਚੋਂ ਆਖਰੀ ਮਿਤੀ, ਅਸਾਮੀਆਂ, ਤਨਖਾਹ, ਉਮਰ ਸੀਮਾ ਅਤੇ ਸਿਲੇਬਸ 1 ਮਿੰਟ ਵਿੱਚ ਸਰਲ ਭਾਸ਼ਾ ਵਿੱਚ ਸਮਝਾਉਂਦਾ ਹੈ।",
    "faq_q3": "📚 ₹10 ਸਟੱਡੀ ਨੋਟਸ ਅਤੇ ਪਿਛਲੇ ਸਾਲਾਂ ਦੇ ਪ੍ਰਸ਼ਨ (PYQ) ਕਿਵੇਂ ਪ੍ਰਾਪਤ ਕਰੀਏ?",
    "faq_a3": "ਪ੍ਰੀਖਿਆ ਚੁਣੋ ਅਤੇ PhonePe, Google Pay ਜਾਂ Paytm ਰਾਹੀਂ ਸਿਰਫ਼ ₹10 ਦਾ UPI ਭੁਗਤਾਨ ਕਰਕੇ ਤੁਰੰਤ ਉੱਚ-ਗੁਣਵੱਤਾ PDF ਡਾਊਨਲੋਡ ਕਰੋ।",
    "faq_q4": "🎂 ਉਮਰ ਕੈਲਕੁਲੇਟਰ ਵਿੱਚ ਰਾਖਵਾਂਕਰਨ ਛੋਟ ਕਿਵੇਂ ਗਿਣੀ ਜਾਂਦੀ ਹੈ?",
    "faq_a4": "ਅਧਿਕਾਰਤ ਕੱਟ-ਆਫ ਮਿਤੀ ਅਤੇ ਜਨਮ ਮਿਤੀ ਅਨੁਸਾਰ OBC 3 ਸਾਲ, SC/ST 5 ਸਾਲ ਅਤੇ PwBD 10-15 ਸਾਲ ਦੀ ਛੋਟ ਆਪਣੇ ਆਪ ਲਾਗੂ ਹੁੰਦੀ ਹੈ।",
    "faq_q5": "🌐 ਕੀ ਪੋਰਟਲ 'ਤੇ ਦਿੱਤੇ ਸਾਰੇ ਲਿੰਕ 100% ਅਧਿਕਾਰਤ ਹਨ?",
