    "faq_q1": "📸 فوٹو اور دستخط کا سائز بدلنے والا ٹول کیسے کام کرتا ہے؟ کیا میری تصویر محفوظ ہے؟",
    "faq_a1": "آپ کی تصویر اور دستخط 100% محفوظ ہیں۔ یہ ٹول مکمل طور پر آپ کے براؤزر کے اندر (Client-side HTML5 Canvas) چلتا ہے، کسی سرور پر اپ لوڈ نہیں ہوتا۔ SSC، UPSC، ریلوے اور پولیس فارم کے لیے 20-50 KB میں سائز بناتا ہے۔",
    "faq_q2": "📑 آفیشل نوٹیفکیشن سرکلر ڈیکوڈر کیا ہے؟",
    "faq_a2": "50-60 صفحات کے طویل نوٹیفکیشن میں سے آخری تاریخ، اسامیاں، تنخواہ، عمر کی حد اور نصاب 1 منٹ میں آسان اردو میں پیش کرتا ہے۔",
    "faq_q3": "📚 ₹10 اسٹڈی نوٹس اور پرانے سوالیہ پرچے کیسے حاصل کریں؟",
    "faq_a3": "امتحان منتخب کریں اور PhonePe، Google Pay یا Paytm سے صرف ₹10 کی فوری UPI ادائیگی کر کے فوراً اعلیٰ معیار کی PDF ڈاؤن لوڈ کریں۔",
    "faq_q4": "🎂 ایج کیلکولیٹر میں ریزرویشن کی رعایت کیسے شمار کی جاتی ہے؟",
    "faq_a4": "آفیشل کٹ آف تاریخ اور تاریخ پیدائش کے مطابق OBC کو 3 سال، SC/ST کو 5 سال، اور معذور افراد کو 10-15 سال کی چھوٹ خود بخود مل جاتی ہے۔",
    "faq_q5": "🌐 کیا پورٹل پر دیے گئے تمام لنکس 100% آفیشل ہیں؟",
    "faq_a5": "جی ہاں! تمام لنکس 24x7 سرکاری پورٹلز (.gov.in, .nic.in) سے تصدیق شدہ ہیں۔",
