    "modal_omr_r1_desc": "ବୃତ୍ତ ବାହାରେ ପେନ୍ ଚଳାନ୍ତୁ ନାହିଁ କିମ୍ବା ଠିକ୍ ଚିହ୍ନ (✓) ଦିଅନ୍ତୁ ନାହିଁ। ସ୍କାନର୍ କେବଳ ସମ୍ପୂର୍ଣ୍ଣ ବୃତ୍ତକୁ ପଢ଼ିଥାଏ।",
    "modal_omr_r2_title": "ରୋଲ୍ ନମ୍ବର ଏବଂ ପୁସ୍ତିକା କୋଡ୍ ସତର୍କତାର ସହ ପୂରଣ କରନ୍ତୁ:",
    "modal_omr_r2_desc": "ପ୍ରଶ୍ନର ଉତ୍ତର ଦେବା ପୂର୍ବରୁ ରୋଲ୍ ନମ୍ବର ଓ ବୁକଲେଟ୍ ସିରିଜ୍ (A, B, C, D) ନିର୍ଭୁଲ ଭାବେ ପୂରଣ କରନ୍ତୁ।",
    "modal_omr_r3_title": "ଗୋଟିଏ ପ୍ରଶ୍ନ ପାଇଁ କେବଳ ଗୋଟିଏ ବୃତ୍ତ ପୂରଣ କରନ୍ତୁ:",
    "modal_omr_r3_desc": "ଯଦି ଦୁଇଟି ବୃତ୍ତ ପୂରଣ କରାଯାଏ ତେବେ ଉତ୍ତର ରଦ୍ଦ ହୁଏ ଏବଂ ନେଗେଟିଭ୍ ମାର୍କିଂ ଲାଗୁ ହୁଏ।",
    "modal_omr_r4_title": "OMR ସିଟ୍‌କୁ କେବେ ଭାଙ୍ଗନ୍ତୁ ନାହିଁ କିମ୍ବା ହ୍ୱାଇଟନର୍ ବ୍ୟବହାର କରନ୍ତୁ ନାହିଁ:",
    "modal_omr_r4_desc": "ବ୍ଲେଡ୍‌ରେ ଘଷିବା କିମ୍ବା ହ୍ୱାଇଟନର୍ ଲଗାଇବା ସମ୍ପୂର୍ଣ୍ଣ ମନା। ବାରକୋଡ୍ ଉପରେ କୌଣସି ଦାଗ ଦିଅନ୍ତୁ ନାହିଁ।",
    "modal_omr_r5_title": "ପରିଦର୍ଶକଙ୍କ ଦସ୍ତଖତ ଏବଂ ଆଙ୍ଗୁଠି ଚିହ୍ନ ଯାଞ୍ଚ କରନ୍ତୁ:",
