    "faq_title": "ବାରମ୍ବାର ପଚରାଯାଉଥିବା ପ୍ରଶ୍ନ (FAQ)",
    "faq_student_desk": "ଛାତ୍ର ସହାୟତା କେନ୍ଦ୍ର (Student Help Desk)",
    "faq_q1": "📸 ଫଟୋ ଓ ଦସ୍ତଖତ ରିସାଇଜର୍ କିପରି କାମ କରେ? ମୋର ଫଟୋ ସୁରକ୍ଷିତ କି?",
    "faq_a1": "ଆପଣଙ୍କ ଫଟୋ ଓ ଦସ୍ତଖତ ୧୦୦% ସୁରକ୍ଷିତ। ଏହି ଉପକରଣ ବ୍ରାଉଜର ଭିତରେ (Client-side HTML5 Canvas) କାର୍ଯ୍ୟ କରେ। SSC, UPSC, ରେଳବାଇ ଓ ପୋଲିସ ଫର୍ମ ପାଇଁ ୨୦-୫୦ KB ରେ ତୁରନ୍ତ ସେଟ୍ କରେ।",
    "faq_q2": "📑 ଅଫିସିଆଲ୍ ବିଜ୍ଞପ୍ତି ସର୍କୁଲାର୍ ଡିକୋଡର୍ କ’ଣ?",
    "faq_a2": "୫୦-୬୦ ପୃଷ୍ଠାର ବିଜ୍ଞପ୍ତିରୁ ଶେଷ ତାରିଖ, ପଦବୀ, ଦରମା, ବୟସ ସୀମା ଓ ପରୀକ୍ଷା ପଦ୍ଧତି ୧ ମିନିଟରେ ସହଜ ଭାଷାରେ ବୁଝାଇଥାଏ।",
    "faq_q3": "📚 ₹୧୦ ଅଧ୍ୟୟନ ନୋଟ୍ସ ଏବଂ ପୂର୍ବ ବର୍ଷ ପ୍ରଶ୍ନ (PYQ) କିପରି ପାଇବେ?",
    "faq_a3": "ପରୀକ୍ଷା ଚୟନ କରି PhonePe, Google Pay ବା Paytm ଦ୍ୱାରା ମାତ୍ର ₹୧୦ UPI ପେମେଣ୍ଟ କରି ତୁରନ୍ତ ଉଚ୍ଚ ମାନର PDF ଡାଉନଲୋଡ୍ କରନ୍ତୁ।",
    "faq_q4": "🎂 ବୟସ ଗଣନାରେ (Age Calculator) ସଂରକ୍ଷଣ ରିହାତି କିପରି ଗଣାଯାଏ?",
    "faq_a4": "ଅଫିସିଆଲ୍ କଟ୍-ଅଫ୍ ତାରିଖ ଓ ଜନ୍ମ ତାରିଖ ଅନୁସାରେ OBC ୩ ବର୍ଷ, SC/ST ୫ ବର୍ଷ ଏବଂ PwBD ୧୦-୧୫ ବର୍ଷ ଛାଡ଼ ସ୍ୱତଃ ପ୍ରଯୁଜ୍ୟ ହୁଏ।",
    "faq_q5": "🌐 ପୋର୍ଟାଲରେ ଥିବା ସମସ୍ତ ଲିଙ୍କ୍ ୧୦୦% ଅଫିସିଆଲ୍ କି?",
    "faq_a5": "ହଁ! ସମସ୍ତ ଲିଙ୍କ୍ ସରକାରୀ ୱେବସାଇଟ୍ (.gov.in, .nic.in) ସହିତ ୨୪x୭ ସତ୍ୟାପିତ।",
