    "faq_student_desk": "छात्र सहायता केंद्र (Student Help Desk)",
    "faq_q1": "📸 फोटो व हस्ताक्षर रिसाइज़र कैसे काम करता है? क्या मेरा फोटो सुरक्षित है?",
    "faq_a1": "रउआ के फोटो और सिग्नेचर 100% सुरक्षित बा। यह टूल ब्राउज़र के अंदर (Client-side HTML5 Canvas पर) चलता है, किसी सर्वर पर अपलोड या स्टोर नहीं होता। यह SSC, UPSC, रेलवे और राज्य पुलिस की आधिकारिक 20-50 KB और पिक्सेल आवश्यकताओं को तुरंत पूरा करता बा।",
    "faq_q2": "📑 आधिकारिक नोटिफिकेशन सर्कुलर डिकोडर क्या है?",
    "faq_a2": "सरकारी भर्ती के 50-60 पन्नों के नोटिफिकेशन में से जरूरी बातें जैसे आवेदन की अंतिम तिथि, कुल पद, वेतनमान, आयु सीमा, परीक्षा पैटर्न और आवश्यक दस्तावेज 1 मिनट में आसान भाषा में प्रस्तुत किए जाते बाड़न।",
    "faq_q3": "📚 ₹10 स्टडी नोट्स और PYQ कैसे प्राप्त करें?",
    "faq_a3": "परीक्षा चयन करके अपन पसंदीदा विषय के नोट्स चुनीं। PhonePe, Google Pay या Paytm से मात्र ₹10 का सीधा UPI QR भुगतान करने पर तुरंत उच्च-गुणवत्ता PDF डाउनलोड अनलॉक हो जाता बा।",
    "faq_q4": "🎂 आयु गणना (Age Calculator) में आरक्षण छूट कैसे गिनी जाती है?",
    "faq_a4": "आयोग की कटऑफ तिथि और जन्मतिथि के आधार पर सटीक गणना की जाती बा। इसमें OBC को 3 वर्ष, SC/ST को 5 वर्ष, PwBD को 10-15 वर्ष और भूतपूर्व सैनिकों को नियमानुसार छूट स्वतः लागू की जाती बा।",
    "faq_q5": "🌐 क्या पोर्टल पर दी गई सभे लिंक्स 100% आधिकारिक (Official) हैं?",
    "faq_a5": "हाँ! हमारा सिस्टम 24x7 स्वायत्त रूप से आधिकारिक आयोगों (.gov.in, .nic.in, .ac.in) के सर्वरों को सत्यापित करता बा। किसी भी फर्जी या भ्रामक विज्ञापन वाली वेबसाइट का लिंक नहीं दिया जाता।",
