    "modal_omr_r4_desc": "ब्लेड से खुरचना, इरेज़र या व्हाइटनर/फ्लूइड लगाना सख्त मना आसा। ओएमआर शीट के बारकोड या टाइमिंग ट्रैक पर कोई अतिरिक्त निशान न लगाएं।",
