const SUPPORTED_LANGUAGES = [
  { code: 'hi', name: 'हिन्दी', label: 'Hindi' },
  { code: 'en', name: 'English', label: 'English' },
  { code: 'hi-latn', name: 'Hinglish', label: 'Hinglish' },
  { code: 'ta', name: 'தமிழ்', label: 'Tamil' },
  { code: 'te', name: 'తెలుగు', label: 'Telugu' },
  { code: 'mr', name: 'मराठी', label: 'Marathi' },
  { code: 'bn', name: 'বাংলা', label: 'Bengali' },
  { code: 'gu', name: 'ગુજરાતી', label: 'Gujarati' },
  { code: 'kn', name: 'ಕನ್ನಡ', label: 'Kannada' },
  { code: 'ml', name: 'മലയാളം', label: 'Malayalam' },
  { code: 'pa', name: 'ਪੰਜਾਬੀ', label: 'Punjabi' },
  { code: 'ur', name: 'اردو', label: 'Urdu' },
  { code: 'or', name: 'ଓଡ଼ିଆ', label: 'Odia' },
  { code: 'sa', name: 'संस्कृतम्', label: 'Sanskrit' },
  { code: 'as', name: 'অসমীয়া', label: 'Assamese' },
  { code: 'mai', name: 'मैथिली', label: 'Maithili' },
  { code: 'bho', name: 'भोजपुरी', label: 'Bhojpuri' },
  { code: 'ne', name: 'नेपाली', label: 'Nepali' },
  { code: 'kok', name: 'कोंकणी', label: 'Konkani' },
  { code: 'sd', name: 'سنڌي / सिंधी', label: 'Sindhi' },
  { code: 'doi', name: 'डोगरी', label: 'Dogri' },
  { code: 'ks', name: 'کٲشُر / कश्मीरी', label: 'Kashmiri' },
  { code: 'sat', name: 'ᱥᱟᱱᱛᱟᱲᱤ', label: 'Santali' },
  { code: 'brx', name: "बर' (बोडो)", label: 'Bodo' }
];

let currentLanguage = (typeof localStorage !== 'undefined' ? localStorage.getItem('sarkariai_lang') : null) || 'hi';

function getTranslation(key, lang = currentLanguage) {
  const dict = I18N_DATA[lang] || I18N_DATA['hi'] || I18N_DATA['en'];
  return dict[key] || I18N_DATA['en'][key] || key;
}

// Universal Bi-Directional Reverse Lookup Dictionary
let universalReverseMap = null;
function getUniversalReverseMap() {
  if (universalReverseMap) return universalReverseMap;
  universalReverseMap = new Map();
  for (const [langCode, dict] of Object.entries(I18N_DATA)) {
    for (const [key, val] of Object.entries(dict)) {
      if (typeof val === 'string') {
        const clean = val.trim();
        if (clean.length > 2) {
          universalReverseMap.set(clean, key);
        }
      }
    }
  }
  return universalReverseMap;
}

// Deep DOM Universal Translation Engine
function translateEntireDOM(lang) {
  if (typeof document === 'undefined') return;
  
  // 1. Process elements with explicit [data-i18n]
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.getAttribute('data-i18n');
    const translation = getTranslation(key, lang);
    if (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA') {
      el.placeholder = translation;
    } else {
      el.innerHTML = translation;
    }
  });

  // 2. Process input and textarea placeholders with data-i18n-placeholder
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
    const key = el.getAttribute('data-i18n-placeholder');
    el.placeholder = getTranslation(key, lang);
  });

  // 3. Process elements with data-i18n-title
  document.querySelectorAll('[data-i18n-title]').forEach(el => {
    const key = el.getAttribute('data-i18n-title');
    el.title = getTranslation(key, lang);
  });

  // 4. Bi-directional Deep Text Node Translation for unlocalized elements
  try {
    const revMap = getUniversalReverseMap();
    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, null, false);
    let node;
    while ((node = walker.nextNode())) {
      const parent = node.parentElement;
      if (!parent || parent.tagName === 'SCRIPT' || parent.tagName === 'STYLE' || parent.hasAttribute('data-i18n')) {
        continue;
      }
      const rawText = node.nodeValue ? node.nodeValue.trim() : '';
      if (rawText.length > 2 && revMap.has(rawText)) {
        const key = revMap.get(rawText);
        const translated = getTranslation(key, lang);
        if (translated && translated !== rawText) {
          node.nodeValue = node.nodeValue.replace(rawText, translated);
        }
      }
    }
  } catch (err) {
    // Non-blocking fallback
  }

  // 5. Update input placeholders without data-i18n
  const searchInput = document.getElementById('globalSearchInput');
  if (searchInput) {
    searchInput.placeholder = getTranslation('search_placeholder', lang);
  }
}

function setLanguage(lang) {
  if (!I18N_DATA[lang]) lang = 'hi';
  currentLanguage = lang;
  if (typeof localStorage !== 'undefined') {
    localStorage.setItem('sarkariai_lang', lang);
  }
  if (typeof document !== 'undefined') {
    document.documentElement.lang = lang;
    
    // RTL support for Urdu, Sindhi, Kashmiri
    if (lang === 'ur' || lang === 'ks') {
      document.documentElement.dir = 'rtl';
    } else {
      document.documentElement.dir = 'ltr';
    }

    translateEntireDOM(lang);

    // Sync all dropdowns on page
    const langSelect = document.getElementById('langSelectDropdown');
    if (langSelect) langSelect.value = lang;
    const mobileLangSelect = document.getElementById('mobileLangSelectDropdown');
    if (mobileLangSelect) mobileLangSelect.value = lang;
  }

  // Dispatch custom event for all portal tools
  if (typeof window !== 'undefined' && typeof CustomEvent !== 'undefined') {
    window.dispatchEvent(new CustomEvent('languageChanged', { detail: { language: lang } }));
  }
}

// Auto init on DOM load
if (typeof document !== 'undefined') {
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
      setLanguage(currentLanguage);
    });
  } else {
    setLanguage(currentLanguage);
  }
}

// Global & CommonJS Exports
if (typeof window !== 'undefined') {
  window.getTranslation = getTranslation;
  window.setLanguage = setLanguage;
  window.translateEntireDOM = translateEntireDOM;
  window.I18N_DATA = I18N_DATA;
  window.SUPPORTED_LANGUAGES = SUPPORTED_LANGUAGES;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    I18N_DATA,
    SUPPORTED_LANGUAGES,
    getTranslation,
    setLanguage,
    translateEntireDOM
  };
}
